  },
];

export function filterAlertCenterMessages(
  items: AlertCenterMessage[],
  tab: string,
): AlertCenterMessage[] {
  if (tab === "unread") {
    return items.filter((m) => m.unread);
  }
  return items;
}

export function filterQueueItems(
  items: QueueRoItem[],
  tab: string,
): QueueRoItem[] {
  if (tab === "active") {
    return items.filter((i) => i.queueTabKey === "active");
  }
  if (tab === "hold") {
    return items.filter((i) => i.queueTabKey === "hold");
  }
  return items;
}

/**
 * Inventis DS Notification panel — Figma 참조.
 * Variants: node 26791:101886 (❖ Notification panel — Alert Center / Queue)
 */

export const FIGMA_NOTIFICATION_FILE_KEY = "MvGuEwW5KUn5VcpSEWm2ve";

export const FIGMA_NOTIFICATION_FILE_BASE = `https://www.figma.com/design/${FIGMA_NOTIFICATION_FILE_KEY}/260303_Inventis-DS--Shadcn-ui`;

/** Variants 섹션 */
